Transitions from a distinct suffix S:
- append x already in S at position p (0-based in S):
  new distinct suffix becomes S[p+1..end] + x, length d-p.
- append x not in S:
  if d < K-1: new suffix S + x, length d+1.
  if d = K-1: only x in S are allowed (the unique missing x is forbidden).

We need to process a sequence with some positions fixed by A and others free.
DP over states of ordered distinct suffixes.
Number of states = sum_{d=0}^{K-1} P(K,d), manageable only for small K.
This matches intended constraints of such problem.

We build all states, transitions for each symbol 1..K and aggregated free-transition lists.
Then process positions 0..N-1, fixing values on the interval where A is placed.

To get f(A):
fixedPosStart chosen arbitrarily, say 0..M-1 at the beginning? Since number is same for every position,
we can fix A at positions 0..M-1. Then answer multiply by (N-M+1).
Colorful property depends only on existence anywhere, unaffected by this choice.

Thus:
f(A) = total with A fixed at prefix - noColorful with A fixed at prefix.
total with A fixed at prefix = K^(N-M), provided all A in [1..K].

Need count of noColorful with prefix A fixed.
Process first M positions with fixed A, remaining N-M free.

Finally answer = (N-M+1) * (K^(N-M) - bad) mod MOD.

*/

public class Main {
    static final long MOD = 1_000_000_007L;

    static int N, K, M;
    static int[] A;

    static ArrayList<int[]> states = new ArrayList<>();
    static HashMap<Long, Integer> idMap = new HashMap<>();
    static int[][] trans; // [state][symbol 1..K] -> next state or -1 if forbidden
    static int[][] freeTo;
    static int[][] freeCnt;

    static long encode(int[] arr) {
        long h = arr.length;
        for (int v : arr) h = h * 131 + v;
        return h;
    }

    static void generateStates(int[] cur, boolean[] used, int len) {
        int[] arr = Arrays.copyOf(cur, len);
        idMap.put(encode(arr), states.size());
        states.add(arr);
        if (len == K - 1) return;
        for (int x = 1; x <= K; x++) {
            if (!used[x]) {
                cur[len] = x;
                used[x] = true;
                generateStates(cur, used, len + 1);
                used[x] = false;
            }
        }
    }

    static int getStateId(int[] arr) {
        return idMap.get(encode(arr));
    }

    static void buildAutomaton() {
        boolean[] used = new boolean[K + 1];
        int[] cur = new int[Math.max(0, K - 1)];
        generateStates(cur, used, 0);

        int S = states.size();
        trans = new int[S][K + 1];

        for (int sid = 0; sid < S; sid++) {
            int[] s = states.get(sid);
            int d = s.length;

            int[] pos = new int[K + 1];
            Arrays.fill(pos, -1);
            for (int i = 0; i < d; i++) pos[s[i]] = i;

            int missing = -1;
            if (d == K - 1) {
                for (int x = 1; x <= K; x++) {
                    if (pos[x] == -1) {
                        missing = x;
                        break;
                    }
                }
            }

            for (int x = 1; x <= K; x++) {
                if (d == K - 1 && x == missing) {
                    trans[sid][x] = -1; // would create a colorful window
                    continue;
                }
                int p = pos[x];
                int[] ns;
                if (p == -1) {
                    ns = new int[d + 1];
                    System.arraycopy(s, 0, ns, 0, d);
                    ns[d] = x;
                } else {
                    int nd = d - p;
                    ns = new int[nd];
                    for (int i = p + 1; i < d; i++) ns[i - (p + 1)] = s[i];
                    ns[nd - 1] = x;
                }
                trans[sid][x] = getStateId(ns);
            }
        }

        freeTo = new int[S][];
        freeCnt = new int[S][];
        for (int sid = 0; sid < S; sid++) {
            HashMap<Integer, Integer> map = new HashMap<>();
            for (int x = 1; x <= K; x++) {
                int to = trans[sid][x];
                if (to != -1) map.put(to, map.getOrDefault(to, 0) + 1);
            }
            int sz = map.size();
            freeTo[sid] = new int[sz];
            freeCnt[sid] = new int[sz];
            int idx = 0;
            for (Map.Entry<Integer, Integer> e : map.entrySet()) {
                freeTo[sid][idx] = e.getKey();
                freeCnt[sid][idx] = e.getValue();
                idx++;
            }
        }
    }

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long countBadWithPrefixFixed() {
        int S = states.size();
        long[] dp = new long[S];
        long[] ndp = new long[S];
        dp[0] = 1; // empty suffix

        for (int i = 0; i < N; i++) {
            Arrays.fill(ndp, 0);
            if (i < M) {
                int x = A[i];
                for (int s = 0; s < S; s++) {
                    long val = dp[s];
                    if (val == 0) continue;
                    int to = trans[s][x];
                    if (to != -1) {
                        ndp[to] += val;
                        if (ndp[to] >= MOD) ndp[to] -= MOD;
                    }
                }
            } else {
                for (int s = 0; s < S; s++) {
                    long val = dp[s];
                    if (val == 0) continue;
                    int[] tos = freeTo[s];
                    int[] cnts = freeCnt[s];
                    for (int j = 0; j < tos.length; j++) {
                        int to = tos[j];
                        ndp[to] = (ndp[to] + val * cnts[j]) % MOD;
                    }
                }
            }
            long[] tmp = dp; dp = ndp; ndp = tmp;
        }

        long bad = 0;
        for (long v : dp) {
            bad += v;
            if (bad >= MOD) bad -= MOD;
        }
        return bad;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        K = fs.nextInt();
        M = fs.nextInt();
        A = new int[M];
        for (int i = 0; i < M; i++) A[i] = fs.nextInt();

        if (M > N) {
            System.out.println(0);
            return;
        }

        for (int x : A) {
            if (x < 1 || x > K) {
                System.out.println(0);
                return;
            }
        }

        if (K == 1) {
            // Every sequence over {1} is colorful, and A must be all 1s (already checked in range).
            // Number of sequences with A fixed at a position is 1.
            System.out.println((N - M + 1) % MOD);
            return;
        }

        buildAutomaton();

        long totalFixed = modPow(K, N - M);
        long bad = countBadWithPrefixFixed();
        long good = (totalFixed - bad) % MOD;
        if (good < 0) good += MOD;

        long ans = good * (N - M + 1L) % MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
